constructor-arg.value:
insert into solicitante(numero,t_persona,nombre,nombre_p,apellidos,apellido_m,rfc1,rfc2,rfc3,curp,domicilio,cat_domicilio1,descripcion_domicilio1,cat_domicilio4,descripcion_domicilio4,
	    cat_domicilio5,descripcion_domicilio5,colonia,celular,correo,sexo,edo_nac_id,cve_nacionalidad,cve_ocupacion,telefono,ubicacion_geografica,fecha_creacion,creado_por,numero_casa,tipo_cliente_id,originario,puesto,cat_domicilio2,descripcion_domicilio2,cat_domicilio3,descripcion_domicilio3) 
		values (nextval('solicitante_s'),?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,current_date,?,?,1,?,?,?,?,?,?) returning numero;

INSERT INTO solicitante_cuenta_simplificada 
				(numero, fecha_creacion, usuario_creacion)
				VALUES(?, current_timestamp, 9);

INSERT INTO public.conceptos_solicitantes
					(id_solicitante, cat_conceptos_id, valor, opctext1, usuario_creacion, fecha_creacion)
					VALUES(?,(select id from cat_conceptos where clave = 'SOLIC_COLONIA'),?,?,9, now());

update conceptos_solicitantes cs set valor = ?, usuario_modificacion = ?, fecha_modificacion = current_timestamp
					where cat_conceptos_id = (select id from cat_conceptos where clave = 'SOLIC_COLONIA')
					and cs.id_solicitante = ?;
